// ==== bundled module: voice-clips.js ====
// voice-clips.js — مقاطع صوت الميس المسجلة (صوت أنثوي طبيعي بالعامية المصرية، Opus).
// Generated by build-voice-clips.py — data lives in voice-clips-data-*.js / voice-clips-text-*.js chunks.
(() => {
  const BY_KEY = Object.assign({}, ...(window.__matthewClipData || []));
  for (const k of Object.keys(BY_KEY)) { const t = k.indexOf("~"); if (t > 0) { const base = k.slice(0, t); BY_KEY[base] = (BY_KEY[base] || "") + BY_KEY[k]; delete BY_KEY[k]; } }
  const BY_TEXT = Object.assign({}, ...(window.__matthewClipText || []));
  const EXACT = Object.assign({}, ...(window.__matthewClipExact || []));
  // Round 3.2.2 P1-5: the chunk arrays are ~56MB of base64 once merged —
  // free them after the snapshot so the audio is not cached twice.
  window.__matthewClipData = null; window.__matthewClipText = null; window.__matthewClipExact = null;
  if (Object.keys(BY_KEY).length < 2000) console.warn("[matthew-clips] only " + Object.keys(BY_KEY).length + " clips loaded (expected ~2100)");
  const DIGITS = {"٠":"0","١":"1","٢":"2","٣":"3","٤":"4","٥":"5","٦":"6","٧":"7","٨":"8","٩":"9"};
  const norm = value => String(value || "").replace(/[٠-٩]/g, c => DIGITS[c]).replace(/[ً-ٰٟـ]/g, "").replace(/[^ء-يa-zA-Z0-9 ]/g, " ").replace(/\s+/g, " ").trim().toLowerCase();
  const urls = {}; const urlOrder = []; const URL_CACHE_MAX = 30; let audio = null;
  const supported = () => { try { const a = audio || new Audio(); return !!a.canPlayType && a.canPlayType('audio/ogg; codecs="opus"') !== ""; } catch (_) { return false; } };
  const urlFor = key => { if (!urls[key]) { const bin = atob(BY_KEY[key]); const bytes = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i); urls[key] = URL.createObjectURL(new Blob([bytes], { type: "audio/ogg" })); urlOrder.push(key); while (urlOrder.length > URL_CACHE_MAX) { const old = urlOrder.shift(); if (old !== key && urls[old]) { try { URL.revokeObjectURL(urls[old]); } catch (_) {} delete urls[old]; } } } return urls[key]; };
  const playKey = key => { if (!BY_KEY[key] || !supported()) return false; try { if (!audio) audio = new Audio(); audio.onended = null; audio.pause(); audio.src = urlFor(key); audio.currentTime = 0; const p = audio.play(); if (p && p.catch) p.catch(() => {}); return true; } catch (_) { return false; } };
  // Round 3.2.2 P0-5: the EXACT map must respect caller language. A bare
  // Latin digit ("5") has an EXACT entry pointing at the ENGLISH tracing
  // clip (tr_ennum_5) — in an Arabic context that is the numbers trap, so
  // Arabic callers skip EXACT for bare digits and use BY_TEXT (the Arabic
  // digit clip, e.g. tr_num_5 / num_digit_15). English callers keep EXACT.
  const isBareDigit = text => /^[0-9٠-٩]+$/.test(String(text || "").trim());
  const keyFor = (text, lang) => {
    const t = String(text || "").trim();
    const arabic = String(lang || "").toLowerCase().startsWith("ar");
    if (arabic && isBareDigit(t)) return BY_TEXT[norm(t)];
    // Numbers-once F7: bare Latin digits 11–20 in English resolve to the
    // English tracing clips (tr_ennum_11..20). The generated EXACT map
    // points here too once the packs rebuild; this keeps the routing
    // correct on the current maps as well.
    if (!arabic && isBareDigit(t)) { const n = Number(t); if (n >= 11 && n <= 20) return "tr_ennum_" + n; }
    return EXACT[t] || BY_TEXT[norm(t)];
  };
  const play = (text, lang) => { const key = keyFor(text, lang); return key ? playKey(key) : false; };
  // Round 3.2.2 P0-4 (review 2.5): element-by-element — an item with no
  // recorded clip is skipped silently instead of dropping the whole
  // question to device TTS.
  const playSequence = (texts, lang) => { const keys = []; for (const t of texts || []) { const k = keyFor(t, lang); if (k) keys.push(k); } if (!keys.length || !supported()) return false; try { if (!audio) audio = new Audio(); let i = 0; const next = () => { if (i >= keys.length) { audio.onended = null; return; } audio.src = urlFor(keys[i++]); const pr = audio.play(); if (pr && pr.catch) pr.catch(() => {}); }; audio.onended = next; next(); return true; } catch (_) { return false; } };
  const stop = () => { try { if (audio) { audio.onended = null; audio.pause(); } } catch (_) {} };
  window.MatthewClips = { playKey, play, playSequence, stop, has: key => !!BY_KEY[key], keys: Object.keys(BY_KEY), count: Object.keys(BY_TEXT).length };
})();

// ==== bundled module: mastery.js ====
"use strict";
/*
 * MatthewMastery — per-skill mastery tracking with spaced repetition.
 *
 * Pedagogy (KG1): a skill is only "mastered" after repeated correct answers
 * spread over time, not after one lucky guess. Correct answers move a skill
 * up a ladder of review intervals (same session -> 1 day -> 3 days -> 1 week
 * -> 2 weeks). A wrong answer drops the skill one rung and schedules a
 * near-term review, so mistakes are revisited soon but without punishment.
 *
 * Storage: localStorage key "matthewMasteryV1"
 *   { "<skillId>": { seen, correct, wrong, streak, level, lastAt, nextReviewAt } }
 * The module is environment-agnostic so it can be unit-tested in Node.
 */
(function (root, factory) {
  const api = factory();
  root.MatthewMastery = api;
  if (typeof module !== "undefined" && module.exports) module.exports = api;
})(typeof window !== "undefined" ? window : globalThis, function () {
  const STORAGE_KEY = "matthewMasteryV1";
  const CROWN_KEY = "matthewCrownV1";
  const DAY = 24 * 60 * 60 * 1000;
  // Review ladder in days, indexed by level 0..4. Level 0 = review today.
  const INTERVALS_DAYS = [0, 1, 3, 7, 14];
  const MAX_LEVEL = INTERVALS_DAYS.length - 1;

  function storage() {
    try {
      if (typeof localStorage !== "undefined") return localStorage;
    } catch (_) { /* storage can throw in private mode */ }
    return null;
  }

  function load() {
    const store = storage();
    if (!store) return {};
    try {
      const raw = JSON.parse(store.getItem(STORAGE_KEY) || "{}");
      return raw && typeof raw === "object" && !Array.isArray(raw) ? raw : {};
    } catch (_) {
      return {};
    }
  }

  function save(data) {
    const store = storage();
    if (!store) return;
    try { store.setItem(STORAGE_KEY, JSON.stringify(data)); } catch (_) { /* quota */ }
  }

  // ---- Royal crown store (scope 10) ----
  // The crown decorates King Matthew for every correct answer: +1 star per
  // correct answer, +1 diamond whenever a skill climbs a mastery level.
  // It lives under its own key so the mastery ladder (level / streak /
  // accuracy / nextReviewAt) never changes shape or meaning.
  function loadCrown() {
    const store = storage();
    if (!store) return { stars: 0, diamonds: 0 };
    try {
      const raw = JSON.parse(store.getItem(CROWN_KEY) || "{}");
      const num = v => {
        const n = Number(v);
        return Number.isFinite(n) ? Math.max(0, Math.floor(n)) : 0;
      };
      return { stars: raw && typeof raw === "object" ? num(raw.stars) : 0, diamonds: raw && typeof raw === "object" ? num(raw.diamonds) : 0 };
    } catch (_) {
      return { stars: 0, diamonds: 0 };
    }
  }

  function saveCrown(crownData) {
    const store = storage();
    if (!store) return;
    try {
      store.setItem(CROWN_KEY, JSON.stringify({
        stars: Math.max(0, Math.floor(Number(crownData.stars) || 0)),
        diamonds: Math.max(0, Math.floor(Number(crownData.diamonds) || 0))
      }));
    } catch (_) { /* quota */ }
  }

  // Current crown counts: { stars, diamonds } (zeros when nothing is stored).
  function crown() {
    return loadCrown();
  }

  // Add bonus stars / diamonds (e.g. +1 diamond for finishing a whole game).
  // Missing or negative amounts count as 0. Returns the updated counts.
  function awardCrown(stars, diamonds) {
    const current = loadCrown();
    current.stars += Math.max(0, Math.floor(Number(stars) || 0));
    current.diamonds += Math.max(0, Math.floor(Number(diamonds) || 0));
    saveCrown(current);
    return { stars: current.stars, diamonds: current.diamonds };
  }

  function blank(now) {
    return { seen: 0, correct: 0, wrong: 0, streak: 0, level: 0, lastAt: 0, nextReviewAt: now };
  }

  // Record one answered question for a skill. Returns the updated record.
  function record(skillId, isCorrect, now) {
    if (!skillId) return null;
    const at = typeof now === "number" ? now : Date.now();
    const data = load();
    const entry = data[skillId] || blank(at);
    const prevLevel = entry.level;
    entry.seen += 1;
    entry.lastAt = at;
    if (isCorrect) {
      entry.correct += 1;
      entry.streak += 1;
      // Two correct answers in a row are needed to climb one rung, so a
      // single lucky tap never marks a KG1 skill as learned.
      if (entry.streak >= 2 && entry.level < MAX_LEVEL) {
        entry.level += 1;
        entry.streak = 0;
      }
    } else {
      entry.wrong += 1;
      entry.streak = 0;
      if (entry.level > 0) entry.level -= 1;
    }
    entry.nextReviewAt = at + INTERVALS_DAYS[entry.level] * DAY;
    data[skillId] = entry;
    save(data);
    // Crown: a star for every correct answer, a diamond when the skill
    // climbs a rung. This only writes the separate crown key; the entry
    // returned above is exactly what the ladder computed.
    if (isCorrect) awardCrown(1, entry.level > prevLevel ? 1 : 0);
    return entry;
  }

  function get(skillId) {
    return load()[skillId] || null;
  }

  function all() {
    return load();
  }

  function accuracy(entry) {
    if (!entry || !entry.seen) return 0;
    return entry.correct / entry.seen;
  }

  // A skill counts as mastered at the top two rungs with solid accuracy.
  function isMastered(entry) {
    return !!entry && entry.level >= 3 && entry.seen >= 4 && accuracy(entry) >= 0.75;
  }

  // Skills whose review date has arrived, weakest first.
  function dueSkills(now) {
    const at = typeof now === "number" ? now : Date.now();
    return Object.entries(load())
      .filter(([, entry]) => entry.seen > 0 && entry.nextReviewAt <= at && !isMastered(entry))
      .sort((a, b) => (accuracy(a[1]) - accuracy(b[1])) || (a[1].nextReviewAt - b[1].nextReviewAt))
      .map(([skillId, entry]) => ({ skillId, ...entry }));
  }

  // Selection weight for question picking: due/weak skills surface more
  // often, new skills get a fair chance, mastered skills mostly rest.
  function weight(skillId, now) {
    const at = typeof now === "number" ? now : Date.now();
    const entry = load()[skillId];
    if (!entry || !entry.seen) return 3; // unseen: introduce it
    if (isMastered(entry)) return entry.nextReviewAt <= at ? 1 : 0.25;
    const dueBoost = entry.nextReviewAt <= at ? 3 : 1;
    return dueBoost * (1 + (1 - accuracy(entry)) * 2);
  }

  function summary(now) {
    const data = load();
    const skills = Object.entries(data).map(([skillId, entry]) => ({
      skillId,
      ...entry,
      accuracy: accuracy(entry),
      mastered: isMastered(entry)
    }));
    const seen = skills.reduce((sum, s) => sum + s.seen, 0);
    const correct = skills.reduce((sum, s) => sum + s.correct, 0);
    return {
      skills,
      totalSeen: seen,
      totalCorrect: correct,
      overallAccuracy: seen ? correct / seen : 0,
      masteredCount: skills.filter(s => s.mastered).length,
      dueCount: dueSkills(now).length,
      strengths: skills.filter(s => s.seen >= 4 && s.accuracy >= 0.8).sort((a, b) => b.accuracy - a.accuracy),
      needsPractice: skills.filter(s => s.seen >= 3 && s.accuracy < 0.6).sort((a, b) => a.accuracy - b.accuracy)
    };
  }

  function reset() {
    const store = storage();
    if (store) { try { store.removeItem(STORAGE_KEY); } catch (_) { /* ignore */ } }
  }

  return {
    STORAGE_KEY,
    CROWN_KEY,
    INTERVALS_DAYS,
    record,
    crown,
    awardCrown,
    get,
    all,
    accuracy,
    isMastered,
    dueSkills,
    weight,
    summary,
    reset
  };
});

// ==== bundled module: parent.js ====
"use strict";
/*
 * Parent dashboard (لوحة ولي الأمر) — id "parentPanel".
 * Other modules already hide #parentPanel when they open, so the panel uses
 * exactly that id. Entry is gated by a simple adult arithmetic question so a
 * KG1 child does not wander in and reset progress by accident.
 * All figures come from MatthewMastery (per-skill records) plus the existing
 * matthewHistory / matthewMathProgress keys — nothing new is collected.
 */
(() => {
  const main = document.querySelector("main");
  const learningList = document.getElementById("learningList");
  const gameList = document.getElementById("gameList");
  if (!main || !learningList || document.getElementById("parentPanel")) return;

  const LABELS = {
    "numbers": "عالم الأرقام",
    "letters": "حروف وكلمات",
    "colors": "الألوان والأشكال",
    "world": "معلومات ممتعة",
    "science": "العلوم والكون",
    "mixed": "اختبار المفاجآت",
    "arabic-letters": "مدرسة الحروف العربية",
    "math-ar": "رحلة الحساب بالعربي",
    "math-en": "الرياضيات بالإنجليزي",
    "listening": "اسمع واختار",
    "tracing": "تتبّع الكتابة",
    "reading-ar": "بداية القراءة بالعربي",
    "reading-en": "قراءة الكلمات الإنجليزية"
  };
  const digits = value => String(value).replace(/[0-9]/g, d => "٠١٢٣٤٥٦٧٨٩"[Number(d)]);
  const pct = value => digits(Math.round(value * 100)) + "٪";

  const panel = document.createElement("section");
  panel.id = "parentPanel";
  panel.className = "academy-panel hidden";
  main.insertBefore(panel, document.querySelector("footer"));

  const card = document.createElement("button");
  card.type = "button";
  card.className = "game-card blue";
  card.innerHTML = '<span class="game-icon">👨‍👩‍👦</span><strong>لوحة ولي الأمر</strong><small>تقدم ماثيو ونقاط القوة والمراجعة</small><span class="play">للكبار فقط ←</span>';
  learningList.append(card);

  let gateA = 0, gateB = 0;

  function open() {
    gameList.classList.add("hidden");
    learningList.classList.add("hidden");
    document.getElementById("quiz")?.classList.add("hidden");
    document.getElementById("result")?.classList.add("hidden");
    panel.classList.remove("hidden");
    renderGate();
    window.scrollTo({ top: 0, behavior: "smooth" });
  }

  function close() {
    panel.classList.add("hidden");
    gameList.classList.remove("hidden");
    learningList.classList.remove("hidden");
  }

  function renderGate() {
    gateA = 6 + Math.floor(Math.random() * 7); // 6..12
    gateB = 5 + Math.floor(Math.random() * 6); // 5..10
    panel.innerHTML =
      '<div class="quiz-top"><button id="parentBack" class="back" type="button">🏠 الرئيسية</button><strong>لوحة ولي الأمر</strong><span>للكبار</span></div>' +
      '<div class="basic-focus"><div class="basic-emoji">🔐</div><h2>سؤال سريع للكبار</h2>' +
      '<p>كام ناتج ' + digits(gateA) + ' + ' + digits(gateB) + '؟</p>' +
      '<div class="parent-gate"><input id="parentGateInput" inputmode="numeric" autocomplete="off" aria-label="ناتج الجمع">' +
      '<button id="parentGateBtn" class="primary" type="button">دخول</button></div>' +
      '<p id="parentGateMsg" class="feedback" aria-live="polite"></p></div>';
    panel.querySelector("#parentBack").onclick = close;
    const check = () => {
      const value = Number(String(panel.querySelector("#parentGateInput").value).replace(/[٠-٩]/g, d => "٠١٢٣٤٥٦٧٨٩".indexOf(d)));
      if (value === gateA + gateB) renderDashboard();
      else panel.querySelector("#parentGateMsg").textContent = "الإجابة مش صح، ركّز وجرب تاني.";
    };
    panel.querySelector("#parentGateBtn").onclick = check;
    panel.querySelector("#parentGateInput").addEventListener("keydown", e => { if (e.key === "Enter") check(); });
  }

  function topLevelSkills(summary) {
    // Collapse granular skills like "letters:<question>" into their category.
    const byCategory = new Map();
    for (const skill of summary.skills) {
      const category = skill.skillId.split(":")[0];
      if (skill.skillId.includes(":") && LABELS[skill.skillId]) continue; // safety
      const agg = byCategory.get(category) || { category, seen: 0, correct: 0, wrong: 0, mastered: false };
      // Category rows recorded directly carry the totals; granular rows are
      // already included in them, so only add granular rows for categories
      // that have no direct row (e.g. arabic-letter:ب).
      agg.seen += skill.seen; agg.correct += skill.correct; agg.wrong += skill.wrong;
      agg.mastered = agg.mastered || skill.mastered;
      byCategory.set(category, agg);
    }
    const direct = new Set(summary.skills.filter(s => !s.skillId.includes(":")).map(s => s.skillId.split(":")[0]));
    return [...byCategory.values()].map(row => {
      // Avoid double counting: if a direct category row exists it already
      // includes its granular children because both are recorded per answer;
      // in that case prefer the direct row only.
      if (direct.has(row.category)) {
        const directRow = summary.skills.find(s => s.skillId === row.category);
        return { ...row, seen: directRow.seen, correct: directRow.correct, wrong: directRow.wrong, mastered: directRow.mastered };
      }
      return row;
    }).filter(row => row.seen > 0).sort((a, b) => b.seen - a.seen);
  }

  function renderDashboard() {
    const mastery = window.MatthewMastery;
    const summary = mastery ? mastery.summary() : { skills: [], totalSeen: 0, totalCorrect: 0, overallAccuracy: 0, masteredCount: 0, dueCount: 0, strengths: [], needsPractice: [] };
    const rows = topLevelSkills(summary);
    let history = [];
    try { history = JSON.parse(localStorage.getItem("matthewHistory") || "[]"); if (!Array.isArray(history)) history = []; } catch (_) { history = []; }

    const rowsHtml = rows.length ? rows.map(row => {
      const acc = row.seen ? row.correct / row.seen : 0;
      const state = row.mastered ? "أتقنها 🏆" : acc >= 0.8 && row.seen >= 4 ? "قوي 💪" : acc < 0.6 && row.seen >= 3 ? "يحتاج تدريب 🌱" : "بيتعلم 📚";
      return '<div class="parent-row"><strong>' + (LABELS[row.category] || row.category) + '</strong>' +
        '<span>' + digits(row.correct) + ' صح من ' + digits(row.seen) + ' (' + pct(acc) + ')</span>' +
        '<span>' + state + '</span></div>';
    }).join("") : '<p class="academy-hint">لسه مفيش محاولات مسجلة. أول ما ماثيو يلعب، التقدم هيظهر هنا.</p>';

    const due = mastery ? mastery.dueSkills().slice(0, 5) : [];
    const dueHtml = due.length ? '<ul class="parent-list">' + due.map(s => '<li>' + (LABELS[s.skillId.split(":")[0]] || s.skillId) + ' — دقة ' + pct(s.seen ? s.correct / s.seen : 0) + '</li>').join("") + '</ul>'
      : '<p>مفيش مهارات مستحقة للمراجعة دلوقتي. 👍</p>';

    const weak = summary.needsPractice[0];
    const recommendation = !summary.totalSeen
      ? "ابدأ بجلسة قصيرة (٥–١٠ دقائق) في الحروف أو الأرقام، وخلي النهاية دايمًا على لعبة بيحبها."
      : weak
        ? "ركّز الجلسة الجاية على «" + (LABELS[weak.skillId.split(":")[0]] || weak.skillId) + "» بجلسات قصيرة ومتكررة، والتطبيق هيرجّع له أسئلتها تلقائيًا بنظام التكرار المتباعد."
        : summary.strengths.length
          ? "ماثيو ثابت في مهارات قوية. خليه يكمل بنفس الإيقاع، وجرّب قسمًا جديدًا هذا الأسبوع لتوسيع اهتماماته."
          : "الاستمرارية أهم من طول الجلسة: ١٠ دقائق يوميًا أفضل من ساعة مرة واحدة في الأسبوع.";

    const historyHtml = history.length ? '<ul class="parent-list">' + history.slice(0, 5).map(h =>
      '<li>' + h.category + ': ' + digits(h.score) + ' من ' + digits(h.total) + ' — ' + new Date(h.at).toLocaleDateString("ar-EG") + '</li>').join("") + '</ul>'
      : '<p>لسه مفيش جلسات اختبار مسجلة.</p>';

    panel.innerHTML =
      '<div class="quiz-top"><button id="parentBack" class="back" type="button">🏠 الرئيسية</button><strong>لوحة ولي الأمر</strong><span>📊</span></div>' +
      '<div class="stats parent-stats"><span>🎯 محاولات <b>' + digits(summary.totalSeen) + '</b></span>' +
      '<span>✅ دقة عامة <b>' + pct(summary.overallAccuracy) + '</b></span>' +
      '<span>🏆 مهارات أتقنها <b>' + digits(summary.masteredCount) + '</b></span>' +
      '<span>⏰ للمراجعة اليوم <b>' + digits(summary.dueCount) + '</b></span></div>' +
      '<h3>التقدم حسب القسم</h3>' + rowsHtml +
      '<h3>مستحق للمراجعة (تكرار متباعد)</h3>' + dueHtml +
      '<h3>توصية الجلسة الجاية</h3><p class="math-tip">' + recommendation + '</p>' +
      '<h3>آخر جلسات الاختبار</h3>' + historyHtml +
      '<button id="parentResetMastery" class="secondary" type="button">تصفير بيانات الإتقان فقط</button>';
    panel.querySelector("#parentBack").onclick = close;
    panel.querySelector("#parentResetMastery").onclick = () => {
      if (window.MatthewMastery) window.MatthewMastery.reset();
      renderDashboard();
    };
  }

  card.addEventListener("click", open);
})();

// ==== bundled module: tracing.js ====
"use strict";
/*
 * Finger tracing (تتبّع الكتابة) — KG1 fine-motor writing practice.
 * The child traces a large guide glyph with a finger (pointer events, so it
 * works with touch and mouse). Coverage is measured against a downsampled
 * mask of the guide glyph itself: the stroke only counts where it follows
 * the letter, which teaches shape and stroke path instead of scribbling.
 * Reaching the coverage goal celebrates, awards the usual stars/points and
 * records mastery under "tracing" / "trace:<glyph>".
 */
(() => {
  const main = document.querySelector("main");
  const learningList = document.getElementById("learningList");
  const gameList = document.getElementById("gameList");
  if (!main || !learningList) return;

  // Every glyph maps to an EXPLICIT recorded clip key (tr_ar_* / tr_en_* /
  // tr_num_* / tr_ennum_*): the text map structurally cannot tell en "1"
  // from ar "١" (same norm "1"), and bare Arabic glyphs collide with damma
  // syllables there, so tracing never speaks by bare-text lookup. Keys are
  // played with MatthewClips.playKey via speakKey below (rescue.js
  // pattern); MatthewVoice.speak(text, lang) takes a LANGUAGE as 2nd arg,
  // not a key. Corpus §13 force-adds every key below.
  const SETS = {
    arLetters: {
      title: "حروف عربية", lang: "ar-EG", dir: "rtl",
      items: ["أ", "ب", "ت", "ث", "ج", "ح", "خ", "د", "ذ", "ر", "ز", "س", "ش", "ص", "ض", "ط", "ظ", "ع", "غ", "ف", "ق", "ك", "ل", "م", "ن", "هـ", "و", "ي"],
      key: i => "tr_ar_" + i
    },
    enLetters: {
      title: "الحروف الإنجليزية", lang: "en-US", dir: "ltr",
      items: "ABCDEFGHIJKLMNOPQRSTUVWXYZ".split(""),
      key: i => "tr_en_" + i
    },
    arNumbers: {
      title: "أرقام عربية", lang: "ar-EG", dir: "rtl",
      items: ["١", "٢", "٣", "٤", "٥", "٦", "٧", "٨", "٩", "١٠"],
      key: i => "tr_num_" + (i + 1)
    },
    enNumbers: {
      title: "الأرقام الإنجليزية", lang: "en-US", dir: "ltr",
      items: "123456789".split("").concat(["10"]),
      key: i => "tr_ennum_" + (i + 1)
    }
  };
  const GOAL = 0.40; // 40% of the guide must be traced — easier for a 5-year-old
  const GRID = 72;   // mask resolution

  const panel = document.createElement("section");
  panel.id = "tracingPanel";
  panel.className = "academy-panel hidden";
  main.insertBefore(panel, document.querySelector("footer"));

  const card = document.createElement("button");
  card.type = "button";
  card.className = "game-card orange";
  card.innerHTML = '<span class="game-icon">✏️</span><strong>اكتب بإصبعك</strong><small>تتبّع الحروف والأرقام واتعلم الكتابة</small><span class="play">يلا نكتب ←</span>';
  learningList.append(card);

  let setId = "arLetters", index = 0, mask = null, covered = null, guideCells = 0, hitCells = 0, drawing = false, done = false;
  let justOpened = false, narrationToken = 0;
  const COLORS = [
    { c: "#e53935", n: "أحمر" }, { c: "#fb8c00", n: "برتقالي" }, { c: "#f9a825", n: "أصفر" },
    { c: "#43a047", n: "أخضر" }, { c: "#1e88e5", n: "أزرق" }, { c: "#8e24aa", n: "بنفسجي" }
  ];
  let traceColor = COLORS[1].c, strokeCtx = null;

  // Round 3.2.2 P0-4: recorded clips ONLY — no device speechSynthesis.
  const speak = (text, lang) => {
    if (window.MatthewVoice && window.MatthewVoice.speak) window.MatthewVoice.speak(text, lang);
  };

  const TRACE_INSTR = "لوّن الحرف من جوّه بس بإصبعك، واختار اللون اللي يعجبك";
  // Round 3.2.1 note 25b (Nancy-lines draft): مس نانسي opens the tracing
  // activity herself (nancy_intro_trace) before the instruction + glyph.
  // Spoken as the first item of the first-open sequence, with the same
  // ~5s gap as the instruction (it is a full sentence, not a bare glyph).
  const NANCY_TRACE_INTRO = "يلا نتتبع الحرف يا ملك ماثيو! امشي على الخط بصوابعك على مهلك، أنت بطل!";
  // Rescue.js pattern: a clip KEY plays first (exact clip, no text-map
  // collision); the spoken text is only the device-TTS fallback.
  const speakKey = (text, key, lang) => {
    try { if (key && window.MatthewClips && window.MatthewClips.playKey(key)) return; } catch (_) {}
    speak(text, lang);
  };
  // Ordered keyed playback (instruction then glyph on first open). The clip
  // runtime exposes no end-of-clip callback, so keyed items are chained
  // with timed gaps: ~5s after the spoken instruction, ~1.3s after a
  // single glyph. playKey pauses the shared audio first, so a late item
  // can only cut the tail of the previous one, never overlap it. The token
  // silences items scheduled by a render the child has already left.
  const speakSequence = (items, tk) => {
    const list = (items || []).filter(Boolean);
    if (!list.length) return;
    let delay = 0;
    list.forEach(it => {
      const text = typeof it === "string" ? it : it.text;
      const key = typeof it === "string" ? null : it.key;
      const lang = typeof it === "string" ? "ar-EG" : (it.lang || "ar-EG");
      setTimeout(() => { if (tk === undefined || tk === narrationToken) speakKey(text, key, lang); }, delay);
      delay += (key === "trace_instr" || key === "nancy_intro_trace") ? 5000 : 1300;
    });
  };

  function open() {
    gameList.classList.add("hidden");
    learningList.classList.add("hidden");
    document.getElementById("quiz")?.classList.add("hidden");
    document.getElementById("result")?.classList.add("hidden");
    document.getElementById("parentPanel")?.classList.add("hidden");
    panel.classList.remove("hidden");
    justOpened = true;
    renderPicker();
    window.scrollTo({ top: 0, behavior: "smooth" });
  }

  function close() {
    narrationToken++;
    panel.classList.add("hidden");
    gameList.classList.remove("hidden");
    learningList.classList.remove("hidden");
    window.MatthewVoice?.stop();
  }

  function buildMask(glyph) {
    const off = document.createElement("canvas");
    off.width = GRID; off.height = GRID;
    const ctx = off.getContext("2d", { willReadFrequently: true });
    if (!ctx) { mask = new Uint8Array(GRID * GRID); covered = new Uint8Array(GRID * GRID); guideCells = 0; return; }
    ctx.fillStyle = "#000";
    ctx.font = "bold 56px Cairo, system-ui, sans-serif";
    ctx.textAlign = "center"; ctx.textBaseline = "middle";
    ctx.fillText(glyph, GRID / 2, GRID / 2 + 2);
    const data = ctx.getImageData(0, 0, GRID, GRID).data;
    mask = new Uint8Array(GRID * GRID);
    guideCells = 0;
    for (let i = 0; i < GRID * GRID; i++) {
      // Dilate by treating a cell as guide if it or a neighbour is filled,
      // so a small finger on a big screen can realistically follow the line.
      mask[i] = data[i * 4 + 3] > 40 ? 1 : 0;
    }
    // dilation pass
    const dilated = new Uint8Array(mask);
    for (let y = 1; y < GRID - 1; y++) for (let x = 1; x < GRID - 1; x++) {
      if (!mask[y * GRID + x]) continue;
      for (let dy = -2; dy <= 2; dy++) for (let dx = -2; dx <= 2; dx++) dilated[(y + dy) * GRID + (x + dx)] = 1;
    }
    mask = dilated;
    for (let i = 0; i < mask.length; i++) guideCells += mask[i];
    covered = new Uint8Array(GRID * GRID);
    hitCells = 0;
  }

  // Picker-first flow (note 16): open() lands on the glyph picker; tapping
  // a glyph opens its trace screen; back from a trace screen returns to the
  // picker, and only the picker's back goes home.
  function renderPicker() {
    const set = SETS[setId];
    const tk = ++narrationToken;
    panel.innerHTML =
      '<div class="quiz-top"><button id="traceBack" class="back" type="button">🏠 الرئيسية</button><strong>✏️ اكتب بإصبعك</strong><span>👑</span></div>' +
      '<div class="trace-sets">' + Object.entries(SETS).map(([id, s]) => '<button type="button" class="trace-set' + (id === setId ? " active" : "") + '" data-set="' + id + '">' + s.title + '</button>').join("") + '</div>' +
      '<div class="lesson-title">اختار حرف أو رقم يا ملك ماثيو 👑</div><p>اضغط على أي حرف أو رقم عشان تكتبه بإصبعك</p>' +
      '<div class="basic-grid letter-picker" dir="' + set.dir + '">' + set.items.map((g, i) => '<button type="button" class="basic-tile" data-glyph="' + i + '"><b>' + g + '</b></button>').join("") + '</div>';
    panel.querySelector("#traceBack").onclick = close;
    panel.querySelectorAll("[data-set]").forEach(b => b.onclick = () => { setId = b.dataset.set; renderPicker(); });
    panel.querySelectorAll("[data-glyph]").forEach(b => b.onclick = () => { index = Number(b.dataset.glyph); render(); });
    setTimeout(() => { if (tk === narrationToken) speakKey("اختار حرف أو رقم يا ملك ماثيو", "trace_picker", "ar-EG"); }, 150);
  }

  function render() {
    const set = SETS[setId];
    const glyph = set.items[index];
    const tk = ++narrationToken;
    done = false;
    panel.innerHTML =
      '<div class="quiz-top"><button id="traceBack" class="back" type="button">→ رجوع</button><strong>✏️ اكتب بإصبعك</strong><span>' +
      String(index + 1).replace(/[0-9]/g, d => "٠١٢٣٤٥٦٧٨٩"[+d]) + ' / ' + String(set.items.length).replace(/[0-9]/g, d => "٠١٢٣٤٥٦٧٨٩"[+d]) + '</span></div>' +
      '<div class="trace-sets">' + Object.entries(SETS).map(([id, s]) => '<button type="button" class="trace-set' + (id === setId ? " active" : "") + '" data-set="' + id + '">' + s.title + '</button>').join("") + '</div>' +
      '<p class="touch-game-instruction">' + TRACE_INSTR + '</p>' +
      '<div class="trace-colors" role="group" aria-label="اختار لون التلوين">' + COLORS.map(col => '<button type="button" class="trace-color' + (col.c === traceColor ? " active" : "") + '" data-color="' + col.c + '" style="background:' + col.c + '" aria-label="لون ' + col.n + '"></button>').join("") + '</div>' +
      '<div class="trace-wrap" dir="' + set.dir + '"><canvas id="traceGuide" width="320" height="320" aria-hidden="true"></canvas><canvas id="traceCanvas" width="320" height="320" aria-label="لوحة تتبع ' + glyph + '"></canvas></div>' +
      '<div class="progress"><div id="traceProgress" style="width:0%"></div></div>' +
      '<p id="traceMsg" class="feedback" aria-live="polite"></p>' +
      '<div class="basic-nav"><button id="tracePrev" class="secondary" type="button">اللي قبله<span class="pager-arrow">→</span></button>' +
      '<button id="traceNext" class="primary" type="button">اللي بعده<span class="pager-arrow">←</span></button>' +
      '<button id="traceListen" class="voice-button" type="button">🔊 اسمع</button>' +
      '<button id="traceClear" class="secondary" type="button">امسح وابدأ تاني</button></div>';
    panel.querySelector("#traceBack").onclick = renderPicker;
    panel.querySelectorAll("[data-set]").forEach(b => b.onclick = () => { setId = b.dataset.set; index = 0; render(); });
    panel.querySelector("#traceListen").onclick = () => speakKey(glyph, set.key(index), set.lang);
    panel.querySelector("#traceClear").onclick = render;
    panel.querySelector("#tracePrev").onclick = () => { index = (index + set.items.length - 1) % set.items.length; render(); };
    panel.querySelector("#traceNext").onclick = () => { index = (index + 1) % set.items.length; render(); };
    setupCanvas(glyph, set);
    panel.querySelectorAll(".trace-color").forEach(b => b.onclick = () => {
      traceColor = b.dataset.color;
      panel.querySelectorAll(".trace-color").forEach(x => x.classList.toggle("active", x === b));
      if (strokeCtx) { strokeCtx.strokeStyle = traceColor; strokeCtx.fillStyle = traceColor; }
    });
    // Instruction narration: on the first render after open, مس نانسي
    // opens the activity, then the instruction, then the glyph; later
    // renders speak the glyph only.
    if (justOpened) {
      justOpened = false;
      speakSequence([{ text: NANCY_TRACE_INTRO, key: "nancy_intro_trace", lang: "ar-EG" }, { text: TRACE_INSTR, key: "trace_instr", lang: "ar-EG" }, { text: glyph, key: set.key(index), lang: set.lang }], tk);
    } else {
      setTimeout(() => { if (tk === narrationToken) speakKey(glyph, set.key(index), set.lang); }, 150);
    }
  }

  function setupCanvas(glyph, set) {
    const guide = panel.querySelector("#traceGuide");
    const canvas = panel.querySelector("#traceCanvas");
    const gtx = guide && guide.getContext("2d");
    const ctx = canvas && canvas.getContext("2d");
    if (!gtx || !ctx) { panel.querySelector("#traceMsg").textContent = "هذا الجهاز لا يدعم لوحة الرسم."; return; }
    buildMask(glyph);
    // Full-resolution glyph mask: paint may only exist inside the letter.
    const maskC = document.createElement("canvas");
    maskC.width = 320; maskC.height = 320;
    const mctx = maskC.getContext("2d", { willReadFrequently: true });
    let maskData = null;
    if (mctx) {
      mctx.fillStyle = "#000";
      mctx.font = "bold 230px Cairo, system-ui, sans-serif";
      mctx.textAlign = "center"; mctx.textBaseline = "middle";
      mctx.fillText(glyph, 160, 172);
      // Dilate the full-resolution mask by ~3px so strokes just outside
      // the visible outline still paint (forgiving edge for a 5-year-old).
      // A centred stroke expands the glyph outline by ~half its width
      // on each side; the destination-in clip below uses this same
      // dilated mask, so tolerant strokes are not erased on pointerup.
      mctx.strokeStyle = "#000";
      mctx.lineWidth = 6;
      mctx.strokeText(glyph, 160, 172);
      try { maskData = mctx.getImageData(0, 0, 320, 320).data; } catch (_) { /* no mask: fall back to grid */ }
    }
    const inside = (x, y) => {
      if (!maskData) return true;
      const xi = Math.round(x), yi = Math.round(y);
      // ~3px tolerance: a point counts as inside if ANY pixel in a
      // 3px neighbourhood has mask alpha > 40, so a finger landing
      // just outside the visible outline still paints.
      for (let dy = -3; dy <= 3; dy++) for (let dx = -3; dx <= 3; dx++) {
        const nx = xi + dx, ny = yi + dy;
        if (nx < 0 || ny < 0 || nx >= 320 || ny >= 320) continue;
        if (maskData[(ny * 320 + nx) * 4 + 3] > 40) return true;
      }
      return false;
    };
    // Draw the guide glyph on the bottom canvas.
    gtx.clearRect(0, 0, 320, 320);
    gtx.font = "bold 230px Cairo, system-ui, sans-serif";
    gtx.textAlign = "center"; gtx.textBaseline = "middle";
    gtx.fillStyle = "rgba(91,60,196,0.18)";
    gtx.fillText(glyph, 160, 172);
    gtx.strokeStyle = "rgba(91,60,196,0.45)";
    gtx.lineWidth = 2;
    gtx.strokeText(glyph, 160, 172);
    // The stroke canvas (top) starts empty; colour comes from the palette.
    ctx.clearRect(0, 0, 320, 320);
    ctx.strokeStyle = traceColor;
    ctx.fillStyle = traceColor;
    ctx.lineWidth = 26;
    ctx.lineCap = "round"; ctx.lineJoin = "round";
    strokeCtx = ctx;

    const pos = event => {
      const rect = canvas.getBoundingClientRect();
      return { x: (event.clientX - rect.left) * (320 / rect.width), y: (event.clientY - rect.top) * (320 / rect.height) };
    };
    const markCoverage = (x, y) => {
      const gx = Math.floor(x / 320 * GRID), gy = Math.floor(y / 320 * GRID);
      for (let dy = -3; dy <= 3; dy++) for (let dx = -3; dx <= 3; dx++) {
        const cx = gx + dx, cy = gy + dy;
        if (cx < 0 || cy < 0 || cx >= GRID || cy >= GRID) continue;
        const cell = cy * GRID + cx;
        if (mask[cell] && !covered[cell]) { covered[cell] = 1; hitCells++; }
      }
      const ratio = guideCells ? hitCells / guideCells : 0;
      panel.querySelector("#traceProgress").style.width = Math.min(100, Math.round(ratio * 100)) + "%";
      if (ratio >= GOAL && !done) finishTracing(glyph, set);
    };
    const dot = p => { ctx.beginPath(); ctx.arc(p.x, p.y, 13, 0, Math.PI * 2); ctx.fill(); };
    let pen = null; // last point INSIDE the glyph, or null while outside
    const paintTo = p => {
      if (!inside(p.x, p.y)) { pen = null; return; }
      if (!pen) { dot(p); pen = p; markCoverage(p.x, p.y); return; }
      const dist = Math.hypot(p.x - pen.x, p.y - pen.y);
      const steps = Math.max(1, Math.ceil(dist / 2)); // 2px steps: gap-free even on fast swipes
      let from = pen;
      for (let s = 1; s <= steps; s++) {
        const sp = { x: pen.x + (p.x - pen.x) * s / steps, y: pen.y + (p.y - pen.y) * s / steps };
        if (inside(sp.x, sp.y)) {
          if (from) { ctx.beginPath(); ctx.moveTo(from.x, from.y); ctx.lineTo(sp.x, sp.y); ctx.stroke(); }
          else dot(sp);
          from = sp;
          markCoverage(sp.x, sp.y); // count coverage along the whole stroke, not only at the endpoint
        } else from = null;
      }
      pen = p;
      markCoverage(p.x, p.y);
    };
    const clipToGlyph = () => {
      if (!maskData) return;
      ctx.save();
      ctx.globalCompositeOperation = "destination-in";
      ctx.drawImage(maskC, 0, 0);
      ctx.restore();
    };
    canvas.addEventListener("pointerdown", event => {
      drawing = true; pen = null;
      try { canvas.setPointerCapture(event.pointerId); } catch (_) {}
      paintTo(pos(event));
      event.preventDefault();
    });
    canvas.addEventListener("pointermove", event => {
      if (!drawing) return;
      paintTo(pos(event));
      event.preventDefault();
    });
    const stop = () => { if (drawing) clipToGlyph(); drawing = false; pen = null; };
    canvas.addEventListener("pointerup", stop);
    canvas.addEventListener("pointercancel", stop);
  }

  function finishTracing(glyph, set) {
    done = true;
    panel.querySelector("#traceMsg").textContent = "برافو يا بطل! كتبت " + glyph + " صح ⭐";
    // No feedback("correct") here: it bumps MatthewVoice's requestId and
    // its delayed (+280ms) praise clip is suppressed by any speak() after
    // it — so completion was effectively silent — while calling it after
    // the clip would stop the clip. The recorded trace_done clip IS the
    // celebration, played by explicit key.
    try {
      window.MatthewMastery?.record("tracing", true);
      window.MatthewMastery?.record("trace:" + glyph, true);
      localStorage.setItem("matthewPoints", Number(localStorage.getItem("matthewPoints") || 0) + 10);
      localStorage.setItem("matthewStars", Number(localStorage.getItem("matthewStars") || 0) + 1);
    } catch (_) { /* storage unavailable */ }
    window.updateStats?.();
    speakKey("برافو يا بطل", "trace_done", "ar-EG");
  }

  card.addEventListener("click", open);
})();

// ==== bundled module: reading.js ====
"use strict";
/*
 * Beginning reading (يلا نقرأ) — the bridge from letters to words.
 *
 * Arabic path (phonics-first, standard KG sequence):
 *   1. Syllables with short vowels: بَ بِ بُ (fatha / kasra / damma)
 *   2. Long syllables with madd: بَا بِي بُو
 *   3. Blending: build real words syllable by syllable (بَا + ب = بَاب)
 * English path: CVC words split into sounds (c-a-t -> cat) with the same
 * listen -> blend -> choose flow.
 * Every quiz answer is recorded in MatthewMastery ("reading-ar"/"reading-en").
 */
(() => {
  const main = document.querySelector("main");
  const learningList = document.getElementById("learningList");
  const gameList = document.getElementById("gameList");
  if (!main || !learningList) return;

  const FATHA = "َ", KASRA = "ِ", DAMMA = "ُ";
  // Letters that connect to what follows use their joined form in syllables.
  const LETTERS = [
    { base: "أ", joined: "أ", name: "الألف" },
    { base: "ب", joined: "بـ", name: "الباء" },
    { base: "ت", joined: "تـ", name: "التاء" },
    { base: "ث", joined: "ثـ", name: "الثاء" },
    { base: "ج", joined: "جـ", name: "الجيم" },
    { base: "ح", joined: "حـ", name: "الحاء" },
    { base: "خ", joined: "خـ", name: "الخاء" },
    { base: "د", joined: "د", name: "الدال" },
    { base: "ذ", joined: "ذ", name: "الذال" },
    { base: "ر", joined: "ر", name: "الراء" },
    { base: "ز", joined: "ز", name: "الزاي" },
    { base: "س", joined: "سـ", name: "السين" },
    { base: "ش", joined: "شـ", name: "الشين" },
    { base: "ص", joined: "صـ", name: "الصاد" },
    { base: "ض", joined: "ضـ", name: "الضاد" },
    { base: "ط", joined: "طـ", name: "الطاء" },
    { base: "ظ", joined: "ظـ", name: "الظاء" },
    { base: "ع", joined: "عـ", name: "العين" },
    { base: "غ", joined: "غـ", name: "الغين" },
    { base: "ف", joined: "فـ", name: "الفاء" },
    { base: "ق", joined: "قـ", name: "القاف" },
    { base: "ك", joined: "كـ", name: "الكاف" },
    { base: "ل", joined: "لـ", name: "اللام" },
    { base: "م", joined: "مـ", name: "الميم" },
    { base: "ن", joined: "نـ", name: "النون" },
    { base: "هـ", joined: "هـ", name: "الهاء" },
    { base: "و", joined: "و", name: "الواو" },
    { base: "ي", joined: "يـ", name: "الياء" }
  ];

  function syllablesFor(letter) {
    // الألف لها أشكال خاصة: الكسرة على همزة تحت الألف (إِ) والمد بالألف (آ).
    if (letter.base === "أ") return [
      { text: "أَ", say: "أَ", label: "فتحة" },
      { text: "إِ", say: "إِ", label: "كسرة" },
      { text: "أُ", say: "أُ", label: "ضمة" },
      { text: "آ", say: "آ", label: "مد بالألف" },
      { text: "إي", say: "إي", label: "مد بالياء" },
      { text: "أو", say: "أو", label: "مد بالواو" }
    ];
    return [
      { text: letter.joined + FATHA, say: letter.base + FATHA, label: "فتحة" },
      { text: letter.joined + KASRA, say: letter.base + KASRA, label: "كسرة" },
      { text: letter.joined + DAMMA, say: letter.base + DAMMA, label: "ضمة" },
      { text: letter.joined + "ا", say: letter.base + "ا", label: "مد بالألف" },
      { text: letter.joined + "ي", say: letter.base + "ي", label: "مد بالياء" },
      { text: letter.joined + "و", say: letter.base + "و", label: "مد بالواو" }
    ];
  }

  // Words built from parts the child can already say: [parts, whole, meaning, emoji]
  const AR_WORDS = [
    { parts: ["بَا", "ب"], word: "بَاب", meaning: "باب البيت", emoji: "🚪" },
    { parts: ["بَ", "قَرَة"], word: "بَقَرَة", meaning: "بقرة بتقول مو", emoji: "🐄" },
    { parts: ["أَ", "سَد"], word: "أَسَد", meaning: "أسد قوي", emoji: "🦁" },
    { parts: ["قَ", "مَر"], word: "قَمَر", meaning: "قمر في السما", emoji: "🌙" },
    { parts: ["سَ", "مَكَة"], word: "سَمَكَة", meaning: "سمكة بتعوم", emoji: "🐟" },
    { parts: ["كَ", "لْب"], word: "كَلْب", meaning: "كلب صديق", emoji: "🐶" },
    { parts: ["قَ", "لَم"], word: "قَلَم", meaning: "قلم بنكتب بيه", emoji: "✏️" },
    { parts: ["بَ", "حْر"], word: "بَحْر", meaning: "بحر كبير", emoji: "🌊" },
    { parts: ["نَ", "جْم"], word: "نَجْم", meaning: "نجم بيلمع", emoji: "⭐" },
    { parts: ["تَا", "ج"], word: "تَاج", meaning: "تاج الملك", emoji: "👑" }
  ];

  const CVC_WORDS = [
    { sounds: ["c", "a", "t"], word: "cat", emoji: "🐱" },
    { sounds: ["d", "o", "g"], word: "dog", emoji: "🐶" },
    { sounds: ["p", "i", "g"], word: "pig", emoji: "🐷" },
    { sounds: ["s", "u", "n"], word: "sun", emoji: "☀️" },
    { sounds: ["b", "u", "s"], word: "bus", emoji: "🚌" },
    { sounds: ["e", "g"], word: "egg", emoji: "🥚" },
    { sounds: ["h", "a", "t"], word: "hat", emoji: "🎩" },
    { sounds: ["b", "e", "d"], word: "bed", emoji: "🛏️" },
    { sounds: ["f", "i", "sh"], word: "fish", emoji: "🐟" },
    { sounds: ["c", "u", "p"], word: "cup", emoji: "🥤" }
  ];

  const panel = document.createElement("section");
  panel.id = "readingPanel";
  panel.className = "academy-panel hidden";
  main.insertBefore(panel, document.querySelector("footer"));

  const card = document.createElement("button");
  card.type = "button";
  card.className = "game-card green";
  card.innerHTML = '<span class="game-icon">📖</span><strong>يلا نقرأ</strong><small>مقاطع وكلمات عربي وإنجليزي</small><span class="play">ابدأ القراءة ←</span>';
  learningList.append(card);

  // Round 3.2.2 P0-4: recorded clips ONLY — no device speechSynthesis.
  const speak = (text, lang) => {
    if (window.MatthewVoice && window.MatthewVoice.speak) window.MatthewVoice.speak(text, lang);
  };
  // Rescue.js pattern: a clip KEY plays first (exact clip, no text-map
  // collision); the spoken text is only the device-TTS fallback. NOTE:
  // MatthewVoice.speak(text, lang) takes a LANGUAGE as 2nd arg, not a key.
  const speakKey = (text, key, lang) => {
    try { if (key && window.MatthewClips && window.MatthewClips.playKey(key)) return; } catch (_) {}
    speak(text, lang);
  };
  // Ordered narration (name then syllables, blend lines): the recorded-clip
  // sequence player resolves texts via EXACT[trim] first (diacritic
  // syllables) then BY_TEXT[norm] (names, blend lines).
  const speakSequence = (texts, lang) => {
    const list = (texts || []).map(t => String(t || "").trim()).filter(Boolean);
    if (!list.length) return;
    try { if (window.MatthewClips && window.MatthewClips.playSequence(list, lang)) return; } catch (_) {}
    if (window.MatthewVoice && window.MatthewVoice.speakSequence) window.MatthewVoice.speakSequence(list, lang);
  };
  const shuffle = a => { const b = [...a]; for (let i = b.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [b[i], b[j]] = [b[j], b[i]]; } return b; };

  let mode = "ar-syllables", letterIndex = 0, wordIndex = 0, picker = true, readToken = 0;

  function open() {
    gameList.classList.add("hidden");
    learningList.classList.add("hidden");
    document.getElementById("quiz")?.classList.add("hidden");
    document.getElementById("result")?.classList.add("hidden");
    document.getElementById("parentPanel")?.classList.add("hidden");
    panel.classList.remove("hidden");
    picker = true;
    render();
    window.scrollTo({ top: 0, behavior: "smooth" });
  }

  function close() {
    readToken++;
    panel.classList.add("hidden");
    gameList.classList.remove("hidden");
    learningList.classList.remove("hidden");
    window.MatthewVoice?.stop();
  }

  // Hierarchical back (note 16): an item screen goes back to its picker,
  // a picker screen goes home — never straight home from an item. The mode
  // tabs in the header are the mode menu, reachable from every picker.
  function header(title, backToPicker) {
    return '<div class="quiz-top"><button id="readBack" class="back" type="button">' + (backToPicker ? "→ رجوع" : "🏠 الرئيسية") + '</button><strong>' + title + '</strong><span>📖</span></div>' +
      '<div class="trace-sets">' +
      '<button type="button" class="trace-set' + (mode === "ar-syllables" ? " active" : "") + '" data-mode="ar-syllables">مقاطع عربي</button>' +
      '<button type="button" class="trace-set' + (mode === "ar-words" ? " active" : "") + '" data-mode="ar-words">كلمات عربي</button>' +
      '<button type="button" class="trace-set' + (mode === "en-cvc" ? " active" : "") + '" data-mode="en-cvc">كلمات إنجليزية</button>' +
      '<button type="button" class="trace-set' + (mode === "quiz" ? " active" : "") + '" data-mode="quiz">تحدي القراءة</button></div>';
  }

  function bindHeader(backToPicker) {
    panel.querySelector("#readBack").onclick = backToPicker ? () => { picker = true; render(); } : close;
    panel.querySelectorAll("[data-mode]").forEach(b => b.onclick = () => { mode = b.dataset.mode; picker = true; render(); });
  }

  function render() {
    if (mode === "ar-syllables") { if (picker) renderSyllablePicker(); else renderSyllables(); }
    else if (mode === "ar-words") { if (picker) renderArWordPicker(); else renderArWord(); }
    else if (mode === "en-cvc") { if (picker) renderCvcPicker(); else renderCvc(); }
    else renderQuiz();
  }

  function renderSyllablePicker() {
    panel.innerHTML = header("📖 مقاطع عربي") +
      '<div class="lesson-title">اختار حرف يا ملك ماثيو 👑</div><p>اضغط على أي حرف عشان تسمع مقاطعه</p>' +
      '<div class="basic-grid letter-picker">' + LETTERS.map((l, i) => '<button type="button" class="basic-tile" data-letter="' + i + '"><b>' + l.base + '</b><small>' + l.name + '</small></button>').join("") + '</div>';
    bindHeader(false);
    panel.querySelectorAll("[data-letter]").forEach(b => b.onclick = () => { letterIndex = Number(b.dataset.letter); picker = false; renderSyllables(); });
  }

  function renderSyllables() {
    const tk = ++readToken;
    const letter = LETTERS[letterIndex];
    const syllables = syllablesFor(letter);
    panel.innerHTML = header("📖 مقاطع حرف " + letter.name, true) +
      '<div class="read-sticky" style="position:sticky;top:0;z-index:5;background:#fff;border-radius:22px;box-shadow:0 6px 18px #30205b1a;display:flex;align-items:center;justify-content:center;gap:14px;padding:10px;margin:10px 0"><span style="font-size:64px;font-weight:900;line-height:1;color:#5b3cc4">' + letter.base + '</span><span style="text-align:right"><b style="font-size:20px;display:block">' + letter.name + '</b><small style="color:#77718b">اضغط على المقطع واسمعه</small></span></div>' +
      '<p class="touch-game-instruction">من الصفر يا بطل: الحرف لوحده ليه صوت، ولما بنحط عليه فتحة أو كسرة أو ضمة صوته بيتغيّر شوية صغيرة. اضغط على كل مقطع واسمع صوته كويس وقوله ورايا، وبعد شوية هنركّب المقاطع على بعض ونعمل منها كلمة كاملة نقراها سوا!</p>' +
      '<div class="read-syllables">' + syllables.map((s, i) => '<button type="button" class="read-syllable" data-syl="' + i + '"><b>' + s.text + '</b><small>' + s.label + '</small></button>').join("") + '</div>' +
      '<div class="basic-nav"><button id="readPrevLetter" class="secondary" type="button">الحرف السابق<span class="pager-arrow">→</span></button>' +
      '<button id="readNextLetter" class="primary" type="button">الحرف التالي<span class="pager-arrow">←</span></button></div>';
    bindHeader(true);
    panel.querySelectorAll("[data-syl]").forEach(b => b.onclick = () => speakKey(syllables[Number(b.dataset.syl)].say, "rd_syl_" + letterIndex + "_" + b.dataset.syl, "ar-EG"));
    panel.querySelector("#readPrevLetter").onclick = () => { letterIndex = (letterIndex + LETTERS.length - 1) % LETTERS.length; renderSyllables(); };
    panel.querySelector("#readNextLetter").onclick = () => { letterIndex = (letterIndex + 1) % LETTERS.length; renderSyllables(); };
    // Full narration on open: the letter name (lsq_name_*) then ALL 6
    // syllables in order (rd_syl_* via the EXACT map) — not a short version.
    setTimeout(() => { if (tk !== readToken) return; speakSequence([letter.name].concat(syllables.map(s => s.say)), "ar-EG"); }, 150);
  }

  function renderArWordPicker() {
    panel.innerHTML = header("📖 نبني كلمة") +
      '<div class="lesson-title">اختار كلمة يا ملك ماثيو 👑</div><p>اضغط على أي كلمة عشان نبنيها سوا</p>' +
      '<div class="basic-grid letter-picker">' + AR_WORDS.map((w, i) => '<button type="button" class="basic-tile" data-word="' + i + '"><span>' + w.emoji + '</span><b>' + w.word + '</b><small>' + w.meaning + '</small></button>').join("") + '</div>';
    bindHeader(false);
    panel.querySelectorAll("[data-word]").forEach(b => b.onclick = () => { wordIndex = Number(b.dataset.word); picker = false; renderArWord(); });
  }

  function renderArWord() {
    const tk = ++readToken;
    const wi = wordIndex % AR_WORDS.length;
    const item = AR_WORDS[wi];
    const blend = item.parts.join("، ") + ". " + item.word;
    panel.innerHTML = header("📖 نبني كلمة", true) +
      '<div class="basic-focus" style="position:sticky;top:0;z-index:5;box-shadow:0 6px 18px #30205b1a"><div class="basic-emoji">' + item.emoji + '</div>' +
      '<div class="read-parts">' + item.parts.map((p, i) => '<button type="button" class="read-part" data-part="' + i + '">' + p + '</button>').join('<span class="read-plus">+</span>') +
      '<span class="read-plus">=</span><button type="button" class="read-part whole" id="readWhole">' + item.word + '</button></div>' +
      '<h2>' + item.meaning + '</h2><p>اضغط على كل مقطع، وبعدين اضغط على الكلمة كلها</p>' +
      '<button id="readWordListen" class="voice-button" type="button">🔊 اسمع الكلمة</button></div>' +
      '<div class="basic-nav"><button id="readPrevWord" class="secondary" type="button">الكلمة السابقة<span class="pager-arrow">→</span></button>' +
      '<button id="readNextWord" class="primary" type="button">كلمة جديدة<span class="pager-arrow">←</span></button></div>';
    bindHeader(true);
    panel.querySelectorAll("[data-part]").forEach(b => b.onclick = () => speakKey(item.parts[Number(b.dataset.part)], "rd_part_" + wi + "_" + b.dataset.part, "ar-EG"));
    panel.querySelector("#readWhole").onclick = () => speakKey(item.word, "rd_word_" + wi, "ar-EG");
    panel.querySelector("#readWordListen").onclick = () => speakKey(blend, "rd_blend_" + wi, "ar-EG");
    panel.querySelector("#readPrevWord").onclick = () => { wordIndex = (wordIndex + AR_WORDS.length - 1) % AR_WORDS.length; renderArWord(); };
    panel.querySelector("#readNextWord").onclick = () => { wordIndex = (wordIndex + 1) % AR_WORDS.length; renderArWord(); };
    // Full narration on open: the whole blend line (rd_blend_*).
    setTimeout(() => { if (tk !== readToken) return; speakKey(blend, "rd_blend_" + wi, "ar-EG"); }, 150);
  }

  function renderCvcPicker() {
    panel.innerHTML = header("📖 كلمات إنجليزية") +
      '<div class="lesson-title">اختار كلمة يا ملك ماثيو 👑</div><p>اضغط على أي كلمة عشان نسمع أصواتها</p>' +
      '<div class="basic-grid letter-picker">' + CVC_WORDS.map((w, i) => '<button type="button" class="basic-tile" data-cvc="' + i + '"><span>' + w.emoji + '</span><b dir="ltr">' + w.word + '</b></button>').join("") + '</div>';
    bindHeader(false);
    panel.querySelectorAll("[data-cvc]").forEach(b => b.onclick = () => { wordIndex = Number(b.dataset.cvc); picker = false; renderCvc(); });
  }

  function renderCvc() {
    const tk = ++readToken;
    const wi = wordIndex % CVC_WORDS.length;
    const item = CVC_WORDS[wi];
    const blend = item.sounds.join(", ") + ". " + item.word;
    panel.innerHTML = header("📖 كلمات إنجليزية", true) +
      '<div class="basic-focus" dir="ltr" style="position:sticky;top:0;z-index:5;box-shadow:0 6px 18px #30205b1a"><div class="basic-emoji">' + item.emoji + '</div>' +
      '<div class="read-parts">' + item.sounds.map((s, i) => '<button type="button" class="read-part" data-sound="' + i + '">' + s + '</button>').join('<span class="read-plus">+</span>') +
      '<span class="read-plus">=</span><button type="button" class="read-part whole" id="readWholeEn">' + item.word + '</button></div>' +
      '<p>اضغط على كل صوت، وبعدين ادمجهم مع بعض</p>' +
      '<button id="readCvcListen" class="voice-button" type="button">🔊 اسمع</button></div>' +
      '<div class="basic-nav"><button id="readPrevCvc" class="secondary" type="button">السابق<span class="pager-arrow">→</span></button>' +
      '<button id="readNextCvc" class="primary" type="button">كلمة جديدة<span class="pager-arrow">←</span></button></div>';
    bindHeader(true);
    panel.querySelectorAll("[data-sound]").forEach(b => b.onclick = () => speakKey(item.sounds[Number(b.dataset.sound)], "rd_cvc_s_" + wi + "_" + b.dataset.sound, "en-US"));
    panel.querySelector("#readWholeEn").onclick = () => speakKey(item.word, "rd_cvc_" + wi, "en-US");
    panel.querySelector("#readCvcListen").onclick = () => speakKey(blend, "rd_cvc_blend_" + wi, "en-US");
    panel.querySelector("#readPrevCvc").onclick = () => { wordIndex = (wordIndex + CVC_WORDS.length - 1) % CVC_WORDS.length; renderCvc(); };
    panel.querySelector("#readNextCvc").onclick = () => { wordIndex = (wordIndex + 1) % CVC_WORDS.length; renderCvc(); };
    // Full narration on open: the whole blend line (rd_cvc_blend_*).
    setTimeout(() => { if (tk !== readToken) return; speakKey(blend, "rd_cvc_blend_" + wi, "en-US"); }, 150);
  }

  function renderQuiz() {
    const tk = ++readToken;
    const useArabic = Math.random() < 0.5;
    let prompt, spoken, lang, skill, choices;
    if (useArabic) {
      const itemIdx = Math.floor(Math.random() * AR_WORDS.length);
      const item = AR_WORDS[itemIdx];
      prompt = item.emoji + " " + item.meaning;
      spoken = item.word; lang = "ar-EG"; skill = "reading-ar";
      choices = shuffle([item, ...shuffle(AR_WORDS.filter(w => w.word !== item.word)).slice(0, 3)]);
      panel.innerHTML = header("📖 تحدي القراءة") +
        '<div class="basic-focus"><div class="basic-emoji">' + item.emoji + '</div><h2>اسمع الكلمة واختارها</h2>' +
        '<button id="readQuizListen" class="voice-button" type="button">🔊 اسمع السؤال</button>' +
        '<div class="read-choices">' + choices.map(c => '<button type="button" class="read-choice" data-word="' + c.word + '">' + c.word + '</button>').join("") + '</div>' +
        '<p id="readQuizMsg" class="feedback" aria-live="polite"></p>' +
        '<button id="readQuizNext" class="primary hidden" type="button">كلمة جديدة<span class="pager-arrow">←</span></button></div>';
      bindHeader();
      // Note 22: the replay button re-speaks the prompt word ONLY — never
      // the choices (this is a listening-identification quiz).
      panel.querySelector("#readQuizListen").onclick = () => speakKey(spoken, "rd_word_" + itemIdx, lang);
      setTimeout(() => { if (tk !== readToken) return; speakKey(spoken, "rd_word_" + itemIdx, lang); }, 200);
      let answered = false;
      panel.querySelectorAll("[data-word]").forEach(b => b.onclick = () => {
        if (answered) return; answered = true;
        const correct = b.dataset.word === item.word;
        try { window.MatthewMastery?.record(skill, correct); window.MatthewMastery?.record("read-word:" + item.word, correct); } catch (_) { /* ignore */ }
        b.classList.add(correct ? "correct" : "wrong");
        panel.querySelectorAll("[data-word]").forEach(x => { x.disabled = true; if (x.dataset.word === item.word) x.classList.add("correct"); });
        panel.querySelector("#readQuizMsg").textContent = correct ? "برافو! قرأت الكلمة صح ⭐" : "دي كلمة " + item.word + ". اسمعها كويس وجرب اللي بعدها.";
        if (correct) window.MatthewVoice?.feedback("correct"); else window.MatthewVoice?.feedback("wrong");
        panel.querySelector("#readQuizNext").classList.remove("hidden");
        panel.querySelector("#readQuizNext").onclick = renderQuiz;
      });
    } else {
      const itemIdx = Math.floor(Math.random() * CVC_WORDS.length);
      const item = CVC_WORDS[itemIdx];
      spoken = item.word; lang = "en-US"; skill = "reading-en";
      choices = shuffle([item, ...shuffle(CVC_WORDS.filter(w => w.word !== item.word)).slice(0, 3)]);
      panel.innerHTML = header("📖 تحدي القراءة") +
        '<div class="basic-focus"><div class="basic-emoji">' + item.emoji + '</div><h2>اسمع واختار الكلمة</h2>' +
        '<button id="readQuizListen" class="voice-button" type="button">🔊 اسمع السؤال</button>' +
        '<div class="read-choices">' + choices.map(c => '<button type="button" class="read-choice" data-word="' + c.word + '">' + c.word + '</button>').join("") + '</div>' +
        '<p id="readQuizMsg" class="feedback" aria-live="polite"></p>' +
        '<button id="readQuizNext" class="primary hidden" type="button">كلمة جديدة<span class="pager-arrow">←</span></button></div>';
      bindHeader();
      // Note 22: the replay button re-speaks the prompt word ONLY — never
      // the choices (this is a listening-identification quiz).
      panel.querySelector("#readQuizListen").onclick = () => speakKey(spoken, "rd_cvc_" + itemIdx, lang);
      setTimeout(() => { if (tk !== readToken) return; speakKey(spoken, "rd_cvc_" + itemIdx, lang); }, 200);
      let answered = false;
      panel.querySelectorAll("[data-word]").forEach(b => b.onclick = () => {
        if (answered) return; answered = true;
        const correct = b.dataset.word === item.word;
        try { window.MatthewMastery?.record(skill, correct); window.MatthewMastery?.record("read-cvc:" + item.word, correct); } catch (_) { /* ignore */ }
        b.classList.add(correct ? "correct" : "wrong");
        panel.querySelectorAll("[data-word]").forEach(x => { x.disabled = true; if (x.dataset.word === item.word) x.classList.add("correct"); });
        panel.querySelector("#readQuizMsg").textContent = correct ? "قراءة جميلة! ⭐" : "الكلمة دي " + item.word + ". اسمعها كويس وجرب اللي بعدها.";
        if (correct) window.MatthewVoice?.feedback("correct"); else window.MatthewVoice?.feedback("wrong");
        panel.querySelector("#readQuizNext").classList.remove("hidden");
        panel.querySelector("#readQuizNext").onclick = renderQuiz;
      });
    }
  }

  card.addEventListener("click", open);
})();

// ==== bundled module: rescue.js ====
// rescue.js — «قصص ومغامرات الملك ماثيو»: أربع مغامرات قصصية بمراحل،
