        return '<button type="button" class="science-card story-card brave s' + bs.id + '" data-brave="' + bs.id + '"><span>' + bs.icon + '</span><b>' + bs.title + '</b><small>' + (open ? 'قصة شجاعة عن مارك ومريم' : '🔒 محتاج ' + bs.stars + ' نجوم — معاك ' + total) + '</small></button>';
