  function gameStatus(board, turn) {
    const moves = allLegalMoves(board, turn);
    if (moves.length === 0) return inCheck(board, turn) ? "checkmate" : "stalemate";
    return inCheck(board, turn) ? "check" : "ongoing";
  }

